        self.val = val
        self.left = left
        self.right = right

def ladoos(root, home, K):
    def dfs(node, distance):
        if not node:
            return 0
        if distance == 0:
            return node.val
        return dfs(node.left, distance - 1) + dfs(node.right, distance - 1)

    def find_home(node, target, path):
        if not node:
            return False
        if node.val == target:
            return True
        if node.left and find_home(node.left, target, path):
            path.append('L')
            return True
        if node.right and find_home(node.right, target, path):
            path.append('R')
            return True
        return False

    path_to_home = []
    find_home(root, home, path_to_home)
    path_to_home.reverse()

    total_ladoos = 0
    current_node = root
    current_distance = 0

    for direction in path_to_home:
        if direction == 'L':
            total_ladoos += dfs(current_node.right, K - current_distance - 1)
            current_node = current_node.left
        elif direction == 'R':
            total_ladoos += dfs(current_node.left, K - current_distance - 1)
            current_node = current_node.right
        current_distance += 1

    total_ladoos += current_node.val
    return total_ladoos
